     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND p."partyCode" = v.code
 WHERE NOT EXISTS (SELECT 1 FROM "PartySite" x WHERE x."partyId" = p.id AND upper(x.name) = upper(v.name));

