    ('RPL20250009', 'returned_to_customer', 'Test Product', 'Test Brand Test Model', 1, NULL, NULL, 'test', 'test', 'Test23453', '2025-08-28T10:53:50.130Z'::timestamptz, '2025-09-04T18:30:00.000Z'::timestamptz, '2025-08-30T00:00:00.000Z'::timestamptz, '2025-08-30T00:00:00.000Z'::timestamptz, '2025-08-30T11:00:51.222Z'::timestamptz)
  ) AS v(no, status, name, model, qty, serial, supplier, centre, courier, docket, sent, expected, back, customer, at)
 WHERE NOT EXISTS (SELECT 1 FROM "ReplacementCase" x WHERE x."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND x."caseNo" = v.no);

INSERT INTO "ReplacementEvent" (id, "storeId", "caseId", kind, "toStatus", note, "createdAt")
SELECT gen_random_uuid()::text, c."storeId", c.id, 'migrated', c.status, v.notes, c."createdAt"
  FROM (VALUES
    ('RPL20250005', 'test'),
    ('RPL20250002', NULL),
    ('RPL20250008', 'test | test'),
    ('RPL20250006', 'COLLECTOR OFFICE POE NOT WORKING'),
    ('RPL20250007', 'test | returned | returned | AAA | RETURNED | RETURN BY ADMIN'),
    ('RPL20250009', 'Test product not working | Test product received in Office | Item sent to client')
  ) AS v(no, notes)
  JOIN "ReplacementCase" c ON c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c."caseNo" = v.no
 WHERE NOT EXISTS (SELECT 1 FROM "ReplacementEvent" e WHERE e."caseId" = c.id AND e.kind = 'migrated');
